import sys

def get_maze():
    with open('maze.txt') as f:
        return [list(r) for r in f.read().split('\n') if r]

def solve():
    maze = get_maze()
    start = None
    end = None
    for r in range(len(maze)):
        for c in range(len(maze[r])):
            if maze[r][c] == '@':
                start = (r, c)
            elif maze[r][c] == 'E':
                end = (r, c)

    from collections import deque
    q = deque([(start, [])])
    visited = set([start])
    dirs = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }

    while q:
        (r, c), path = q.popleft()
        if (r, c) == end:
            return path
        for d, (dr, dc) in dirs.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != '#':
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), path + [d]))
    return None

ans = solve()
