from collections import deque

with open('maze.txt', 'r') as f:
    maze = [list(line.strip()) for line in f if line.strip()]

def get_pos(out):
    for line in out.splitlines():
        if "You are at row" in line:
            parts = line.split()
            r = int(parts[parts.index("row") + 1].strip(","))
            c = int(parts[parts.index("column") + 1].strip("."))
            return r, c
    return None

def find_path(start, end, maze):
    q = deque([(start, [])])
    visited = set([start])
    directions = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }

    while q:
        (r, c), path = q.popleft()
        if (r, c) == end:
            return path
        for d, (dr, dc) in directions.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != '#':
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), path + [d]))
    return None

