import sys
from collections import deque

with open('maze.txt', 'r') as f:
    maze = [list(line.strip()) for line in f if line.strip()]

start = None
end = None

for r in range(len(maze)):
    for c in range(len(maze[r])):
        if maze[r][c] == '@':
            start = (r, c)
        elif maze[r][c] == 'E':
            end = (r, c)

if not start or not end:
    print("Start or end not found")
    sys.exit(1)

queue = deque([(start, [])])
visited = set([start])

dirs = {
    'up': (-1, 0),
    'down': (1, 0),
    'left': (0, -1),
    'right': (0, 1)
}

while queue:
    (r, c), path = queue.popleft()
    if (r, c) == end:
        print(" ".join(path))
        sys.exit(0)

    for dname, (dr, dc) in dirs.items():
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]):
            if maze[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), path + [dname]))

